// Part 13 lesson 8 reference solution: a Hough transform accumulator for straight lines, 16 angles, one angle per clock.
//
// A line is the set of points (x, y) with x*cos(t) + y*sin(t) = rho. For each edge point and each of the NT = 16 angles t_k = k * pi / 16 (k = 0 .. 15, in steps of
// 11.25 degrees) the block computes   rho_k = ((x * ctab(k) + y * stab(k) + 64) >>> 7) + ROFF   (cos and sin are in Q7: ctab(k) = round(128 cos t_k), given below;
// >>> is the arithmetic shift, floor) and adds one to the accumulator cell acc[k][rho_k]. ROFF = 48 makes the index non-negative for x, y in 0 .. 63 (rho runs from
// about -64 to +64, of which cells 0 .. NR-1 = 0 .. 95 are kept; a point whose index falls outside is not counted).
// Handshake: pt_valid with busy low presents a point (pt_x, pt_y 8 bits each); the block then sets busy while it processes the point; a point presented while busy is ignored.
// clear (a one-clock pulse, only when not busy) zeroes every cell in ONE clock. Read port: rd_theta (k), rd_rho (cell) select a cell and rd_cnt shows its 16-bit count one clock later.
// The tables are computed by a CORDIC or a small ROM; lesson 8 discusses which and the cost.
//
// The accumulator is held in one true dual-port block RAM. Port A is shared between the
// internal read and write phases of the read-modify-write operation. Port B remains the
// synchronous user read port. A cell whose valid bit is 0 reads as 0, so clear still
// zeroes every cell in one clock by clearing the valid bits, not the RAM.
module hough_cell_ram #(
    parameter int N = 1536
) (
    input  logic        clk,
    input  logic        we,
    input  logic [10:0] waddr,
    input  logic [15:0] wdata,
    input  logic [10:0] raddr,
    output logic [15:0] rdata
);
    (* ram_style = "block" *) logic [15:0] mem [0:N-1];
    always_ff @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule

module hough_cell_tdp #(
    parameter int N = 1536
) (
    input  logic        clk,
    input  logic        ena,
    input  logic        wea,
    input  logic [10:0] addra,
    input  logic [15:0] dina,
    output logic [15:0] douta,
    input  logic        enb,
    input  logic [10:0] addrb,
    output logic [15:0] doutb
);
    (* ram_style = "block" *) logic [15:0] mem [0:N-1];

    always_ff @(posedge clk) begin
        if (ena) begin
            if (wea)
                mem[addra] <= dina;
            else
                douta <= mem[addra];
        end
    end

    always_ff @(posedge clk) begin
        if (enb)
            doutb <= mem[addrb];
    end
endmodule

module hough #(
    parameter int NT = 16,
    parameter int NR = 96,
    parameter int ROFF = 48
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        pt_valid,
    input  logic [7:0]  pt_x,
    input  logic [7:0]  pt_y,
    output logic        busy,
    input  logic        clear,
    input  logic [3:0]  rd_theta,
    input  logic [6:0]  rd_rho,
    output logic [15:0] rd_cnt
);
    function automatic signed [8:0] ctab(input [3:0] k);
        case (k)
            4'd0: ctab = 128;
            4'd1: ctab = 126;
            4'd2: ctab = 118;
            4'd3: ctab = 106;
            4'd4: ctab = 91;
            4'd5: ctab = 71;
            4'd6: ctab = 49;
            4'd7: ctab = 25;
            4'd8: ctab = 0;
            4'd9: ctab = -25;
            4'd10: ctab = -49;
            4'd11: ctab = -71;
            4'd12: ctab = -91;
            4'd13: ctab = -106;
            4'd14: ctab = -118;
            4'd15: ctab = -126;
            default: ctab = 0;
        endcase
    endfunction

    function automatic signed [8:0] stab(input [3:0] k);
        case (k)
            4'd0: stab = 0;
            4'd1: stab = 25;
            4'd2: stab = 49;
            4'd3: stab = 71;
            4'd4: stab = 91;
            4'd5: stab = 106;
            4'd6: stab = 118;
            4'd7: stab = 126;
            4'd8: stab = 128;
            4'd9: stab = 126;
            4'd10: stab = 118;
            4'd11: stab = 106;
            4'd12: stab = 91;
            4'd13: stab = 71;
            4'd14: stab = 49;
            4'd15: stab = 25;
            default: stab = 0;
        endcase
    endfunction

    localparam int NC = NT * NR;

    typedef enum logic [1:0] {
        IDLE,
        READ_CELL,
        WRITE_CELL
    } state_t;

    state_t state;
    logic [7:0] x, y;
    logic [3:0] angle;
    logic signed [17:0] px_calc, py_calc;
    logic signed [31:0] sum_calc;
    integer rho_calc;
    logic [10:0] cell_addr;
    logic [10:0] ridx;
    logic [15:0] q_internal, q_user;
    logic cell_was_valid;
    logic [NC-1:0] vld;
    logic vld_user;

    initial vld = '0;

    always_comb begin
        px_calc = $signed({1'b0, x}) * ctab(angle);
        py_calc = $signed({1'b0, y}) * stab(angle);
        sum_calc = $signed(px_calc) + $signed(py_calc) + 32'sd64;
        rho_calc = (sum_calc >>> 7) + ROFF;
        cell_addr = 11'(angle * NR + rho_calc);
        ridx = 11'(rd_theta * NR + rd_rho);
    end

    wire cell_in_range = (rho_calc >= 0) && (rho_calc < NR);
    wire ram_write = rst_n && (state == WRITE_CELL);
    wire [15:0] incremented_cell =
        (cell_was_valid ? q_internal : 16'd0) + 16'd1;

    assign busy = (state != IDLE);
    assign rd_cnt = vld_user ? q_user : 16'd0;

    hough_cell_tdp #(.N(NC)) u_cells (
        .clk   (clk),
        .ena   (state == READ_CELL || ram_write),
        .wea   (ram_write),
        .addra (cell_addr),
        .dina  (incremented_cell),
        .douta (q_internal),
        .enb   (1'b1),
        .addrb (ridx),
        .doutb (q_user)
    );

    always_ff @(posedge clk) begin
        vld_user <= vld[ridx];

        if (!rst_n) begin
            state <= IDLE;
            angle <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (clear)
                        vld <= '0;

                    if (pt_valid && !busy) begin
                        x <= pt_x;
                        y <= pt_y;
                        angle <= 4'd0;
                        state <= READ_CELL;
                    end
                end

                READ_CELL: begin
                    cell_was_valid <= vld[cell_addr];
                    state <= WRITE_CELL;
                end

                WRITE_CELL: begin
                    if (cell_in_range)
                        vld[cell_addr] <= 1'b1;

                    if (angle == NT - 1) begin
                        state <= IDLE;
                    end else begin
                        angle <= angle + 4'd1;
                        state <= READ_CELL;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule
``` 
NOTE: Combined the accumulator into one dual-port block RAM, sharing port A across the internal read and write phases; this adds one clock per angle versus the original pipelined design (about 16 clocks per point).

